INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID1', N'CH_ID_MOB_INT', N'FAQ_732018175000', N'What do I need to enroll for mobile and online banking?', N'To enroll, you need to identify yourself by providing: 
 1. Last Name
 2. SSN 
 3. Date of Birth 
 Then validate with a Secure Access Code or Card CVV.', N'SID_ACTIVE', N'FAQ_CAT_ID1', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID10', N'CH_ID_MOB_INT', N'FAQ_732018175001', N'How can I update my contact details registered with the bank?', N'You can update your phone numbers, email ids and addresses registered with the bank from the Profile section of the mobile and online banking apps.', N'SID_ACTIVE', N'FAQ_CAT_ID8', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID11', N'CH_ID_MOB_INT', N'FAQ_732018175102', N'Can I transfer money to own accounts in the same bank?', N'Yes, you can transfer money within your eligible accounts in the bank from the mobile and online banking applications.', N'SID_ACTIVE', N'FAQ_CAT_ID4', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID12', N'CH_ID_MOB_INT', N'FAQ_732018175303', N'How can I verify my accounts in external accounts for Fund Transfers?', N'You can use the following options: 
 1. Provide your netbbanking credentials of the bank for which the account is being added - Instant verification.
 2. Enter the trial deposits amount values that were deposited in the external account - Takes up to 2 days.', N'SID_ACTIVE', N'FAQ_CAT_ID4', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID13', N'CH_ID_MOB_INT', N'FAQ_732018175304', N'Can I pay my loan dues from the mobile and online banking apps?', N'Yes, you can pay your loan due amount from the online banking application. You can view your due amount and make partial or full payment of the amount due.', N'SID_ACTIVE', N'FAQ_CAT_ID4', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID14', N'CH_ID_MOB_INT', N'FAQ_732018175305', N'What types of fund transfers are supported with the mobile and online banking applications?', N'You can make the following types of fund transfers: 
1. To your own accounts in the same bank
2. To others in the same bank
3. To your own or other accounts in different banks
4. Wire Transfers (Domestic/International)', N'SID_ACTIVE', N'FAQ_CAT_ID4', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID15', N'CH_ID_MOB_INT', N'FAQ_732018175306', N'Can I set up recurring or future dated transfer?', N'Yes. You can schedule future-dated transfers. Recurring transfers can be made at regular intervals, such as daily, weekly, every 2 weeks, monthly, etc.', N'SID_ACTIVE', N'FAQ_CAT_ID4', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID16', N'CH_ID_MOB_INT', N'FAQ_732018175307', N'Can I cancel a scheduled transfer?', N'Yes, you can cancel a scheduled transfer. It will cancel and stop all the pending transfers in case of recurring transactions.', N'SID_ACTIVE', N'FAQ_CAT_ID4', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID17', N'CH_ID_MOB_INT', N'FAQ_732018175308', N'How can I communicate with the bank from the mobile and online banking applications?', N'You can send messages to the bank in a secure method from the mobile and online banking applications.', N'SID_ACTIVE', N'FAQ_CAT_ID9', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID18', N'CH_ID_MOB_INT', N'FAQ_732018175309', N'Can I send attachments with my messages to the bank from the app?', N'Yes, you can send up to 5 attachments per message. Each attachment can have a maximum size of 1 MB. ', N'SID_ACTIVE', N'FAQ_CAT_ID9', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID19', N'CH_ID_MOB_INT', N'FAQ_732018175310', N'What types of attachments are supported in the messages?', N'The application supports the following file types: 1.txt 2.doc 3.docx 4.pdf', N'SID_ACTIVE', N'FAQ_CAT_ID9', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID2', N'CH_ID_MOB_INT', N'FAQ_732018174711', N'What are the sign in options available for the mobile banking app?', N'You can use the following options: 
 1. Username and Password 
 2. Sign in PIN 
 3. Facial Recognition 
 4. Fingerprint/Touch ID on supported devices', N'SID_ACTIVE', N'FAQ_CAT_ID1', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID20', N'CH_ID_MOB_INT', N'FAQ_732018175312', N'What is bill payment?', N'Bill Pay is an online service that allows you to pay your bills through mobile/online banking. You can set up one-time payments, schedule future payments or create recurring payments', N'SID_ACTIVE', N'FAQ_CAT_ID5', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID21', N'CH_ID_MOB_INT', N'FAQ_732018175313', N'How do I register a new biller in mobile/online banking?', N'To register a new biller follow the below steps:
 1. Login into mobile/online banking application
 2. Select "Pay a bill" ---> Add New Payee
 3. Provide required biller details and add the payee', N'SID_ACTIVE', N'FAQ_CAT_ID5', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID22', N'CH_ID_MOB_INT', N'FAQ_732018175314', N'Is there a limit to the number of bills I can pay online?', N'No. There is no limit in the number of bills you can pay online.', N'SID_ACTIVE', N'FAQ_CAT_ID5', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID23', N'CH_ID_MOB_INT', N'FAQ_732018175315', N'How can I stop a scheduled payment?', N'Yes, you can cancel a scheduled payment. Go to scheduled payments list in bill pay and find the cancel option to stop a payment.', N'SID_ACTIVE', N'FAQ_CAT_ID5', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID24', N'CH_ID_MOB_INT', N'FAQ_732018175316', N'Can I delete a registered biller from my account?', N'Yes, you can delete a registered biller. Deleting a biller will stop scheduled payments and all the payments under process for that biller.', N'SID_ACTIVE', N'FAQ_CAT_ID5', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID25', N'CH_ID_MOB_INT', N'FAQ_732018175317', N'What can I use Person-to-Person for?', N'You can use Person-to-Person to send or request payment from others. Below are some examples where you can use Person-to-Person.
 
 1. Send a monetary gift to family or friends
 2. Pay back a friend or co-worker
 3. Pay vendors such as your baby sitter, gardener, or landlord
 4. Request money from a friend or family member', N'SID_ACTIVE', N'FAQ_CAT_ID6', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID26', N'CH_ID_MOB_INT', N'FAQ_732018175318', N'How do I add a new person as my recipient?', N'To add a new payee follow the below steps:
 1. Login into mobile/online banking application
 2. Go to "Person-to-Person" and select "Add Recipient"
 3. Enter name, phone number or email and click"Add"', N'SID_ACTIVE', N'FAQ_CAT_ID6', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID27', N'CH_ID_MOB_INT', N'FAQ_732018175319', N'How does send work in Person-to-Person?', N'To send money to someone, enter their name, e-mail address or mobile phone number, the amount you want to send, and a transaction note. Follow the instructions to complete the payment/transfer. The funds will automatically be withdrawn from your account and sent electronically to their account', N'SID_ACTIVE', N'FAQ_CAT_ID6', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID28', N'CH_ID_MOB_INT', N'FAQ_732018175320', N'How does receive work in Person-to-Person?', N'To request money from someone, enter their name, e-mail address or mobile phone number, the amount requested, and a personal message. Follow the instructions to complete the payment/transfer request. They will receive a notification and instructions on how to complete the payment. Once they confirm, the funds will automatically be debited from their account and credited to your account', N'SID_ACTIVE', N'FAQ_CAT_ID6', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID29', N'CH_ID_MOB_INT', N'FAQ_732018175321', N'Can I edit or delete a payee from my registered payee list?', N'Yes. You can edit or delete a payee. Go to "Person-to-Person" and choose "Manage Recipient". 
 1. To delete, click delete and confirm to remove a payee from your list.
 2. To edit, click on edit, change the required details and update. Confirm the same to save the changes.', N'SID_ACTIVE', N'FAQ_CAT_ID6', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID3', N'CH_ID_MOB_INT', N'FAQ_732018175422', N'What are the sign in options available for the online banking application?', N'You can use your username and password to sign into the online banking app.', N'SID_ACTIVE', N'FAQ_CAT_ID1', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID30', N'CH_ID_MOB_INT', N'FAQ_732018175323', N'Can I schedule a send/request for a payee?', N'Yes. You can schedule a send/request money transfer by choosing a future date for the transaction', N'SID_ACTIVE', N'FAQ_CAT_ID6', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID31', N'CH_ID_MOB_INT', N'FAQ_732018175324', N'Can I schedule a recurring send to a payee?', N'Yes. You can schedule a transaction, choose the frequency (Daily, Monthly, Weekly, etc) and specify the end date or duration to stop the recurrence.', N'SID_ACTIVE', N'FAQ_CAT_ID6', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID32', N'CH_ID_MOB_INT', N'FAQ_732018175325', N'Where can I find my account statement?', N'Sign in to your mobile/online banking application. Select the required acccount and choose "Account Statements". Select the required period to get the account statement.', N'SID_ACTIVE', N'FAQ_CAT_ID10', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID33', N'CH_ID_MOB_INT', N'FAQ_732018175326', N'Can I schedule an account statement to my email?', N'No, you can''t schedule and send an account statement to your email.', N'SID_ACTIVE', N'FAQ_CAT_ID10', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID34', N'CH_ID_MOB_INT', N'FAQ_732018175327', N'Can I download my account statement?', N'Yes. You have the options to download, print, or send the statement to your email.', N'SID_ACTIVE', N'FAQ_CAT_ID10', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID35', N'CH_ID_MOB_INT', N'FAQ_732018175328', N'Can I get my account statement for any period?', N'Yes. Mention the start and end date to download statement for the required period.', N'SID_ACTIVE', N'FAQ_CAT_ID10', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID36', N'CH_ID_MOB_INT', N'FAQ_732018175329', N'What are the formats in which I can download the statement?', N'You can download your account statement in Excel, PDF, and Quicken formats.', N'SID_ACTIVE', N'FAQ_CAT_ID10', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID37', N'CH_ID_MOB_INT', N'FAQ_732018175330', N'Can I request for a card from my mobile/online banking application?', N'Yes. You can place a request for a new card from your mobile/online banking application.', N'SID_ACTIVE', N'FAQ_CAT_ID3', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID38', N'CH_ID_MOB_INT', N'FAQ_732018175331', N'What are different card management options available online', N'Following are the options availabe to manage your card online:
 1. Change PIN
 2. Lock Card
 3. Replace Card
 4. Cancel Card
 5. Report Stolen/Lost', N'SID_ACTIVE', N'FAQ_CAT_ID3', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID39', N'CH_ID_MOB_INT', N'FAQ_732018175332', N'How can I change my debit/credit card PIN online?', N'Login to your mobile/online banking application. Go to "Manage Card" section, select the required card and select "Change PIN" option. Provide the reason for chaning the PIN and confirm your request. You will receive a mail with new PIN.', N'SID_ACTIVE', N'FAQ_CAT_ID3', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID4', N'CH_ID_MOB_INT', N'FAQ_732018174833', N'I forgot my username? How can I sign in to the application?', N'Click on Forgot and provide the information to identify yourself. Validate your identity with the Secure Access Code or Card CVV. If validated correctly, you''ll be able to retreive your username.', N'SID_ACTIVE', N'FAQ_CAT_ID1', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID40', N'CH_ID_MOB_INT', N'FAQ_732018175334', N'I have lost my card. How can I report it online?', N'Login into your mobile/online banking application. Go to "Manage Card" section, select the required card. Select Report stolen/lost option. You have options to either call customer care directly or to log a report online.', N'SID_ACTIVE', N'FAQ_CAT_ID3', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID41', N'CH_ID_MOB_INT', N'FAQ_732018175335', N'Can I withdraw my stolen/lost report online to reactivate my card?', N'No, you can''t withdraw stolen/lost report online.', N'SID_ACTIVE', N'FAQ_CAT_ID3', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID42', N'CH_ID_MOB_INT', N'FAQ_732018175336', N'If I lock my card can I unlock in again online?', N'Yes. You can unlock your locked card online with mobile/online banking application. The card can then be used to perform all transactions.', N'SID_ACTIVE', N'FAQ_CAT_ID3', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID43', N'CH_ID_MOB_INT', N'FAQ_732018175337', N'Can I use my debit/credit card to pay billsin online banking?', N'Yes. Login into your mobile/online banking and register with your card details to make bill payments.', N'SID_ACTIVE', N'FAQ_CAT_ID3', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID44', N'CH_ID_MOB_INT', N'FAQ_732018175338', N'Is it safe to bank and pay bills online?', N'When you register for online banking, you create a unique username and password. So you and only you can access your accounts. Kindly ensure that you do not write it down in any form or share it with anyone. You are responsible for protecting your password, account details and for providing prompt notification in case of an unauthorized transaction.', N'SID_ACTIVE', N'FAQ_CAT_ID7', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID45', N'CH_ID_MOB_INT', N'FAQ_732018175339', N'How is online banking security measured?', N'Online Banking uses industry-standard security protocols that leverage encryption for transferring data. Encryption helps create a secure environment for the information being transferred between your browser and Temenos Digital DBX Bank. The protocols protect data through Authentication, Encryption and Data integrity.', N'SID_ACTIVE', N'FAQ_CAT_ID7', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID46', N'CH_ID_MOB_INT', N'FAQ_732018175340', N'How does the security protocols protect data?', N'These protocols protect data in 3 key ways:
 1. Authentication ensures that you are communicating with the bank only and protects impersonation by another computer
 2. Encryption scrambles transferred data so that it cannot be read by unauthorized parties
 3. Data integrity, in terms of data and network security, assures that information can only be accessed and modified by those authorized to do so.', N'SID_ACTIVE', N'FAQ_CAT_ID7', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID47', N'CH_ID_MOB_INT', N'FAQ_732018175341', N'Is it secure to do online/mobile banking outside my country?', N'Yes, you can do online/mobile banking from anywhere in the world with the same level of security.', N'SID_ACTIVE', N'FAQ_CAT_ID7', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID48', N'CH_ID_MOB_INT', N'FAQ_732018175342', N'Is it safe to access online banking feature from multiple computers', N'Yes, you can access online banking feature from multiple computers with the same level of security. ', N'SID_ACTIVE', N'FAQ_CAT_ID7', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID49', N'CH_ID_MOB_INT', N'FAQ_732018175343', N'Is it safe to use mobile browser to do online banking?', N'Yes, it is safe to do online banking on mobile browser. However, it is recommended that you logout and close your browser after performing online banking.', N'SID_ACTIVE', N'FAQ_CAT_ID7', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID5', N'CH_ID_MOB_INT', N'FAQ_732018175344', N'I forgot my password? How can I sign in to the application?', N'Click on Forgot and provide the information to identify yourself. Validate your identity with the Secure Access Code or Card CVV. If validated correctly, you''lll be able to reset your password.', N'SID_ACTIVE', N'FAQ_CAT_ID1', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID50', N'CH_ID_MOB_INT', N'FAQ_732018175345', N'I share my computer with someone who also uses Online Banking. Can both of us sign in from this computer?', N'Yes. You can both use the same computer to sign in to your individual online banking account safely; you won''t see each other''s information. There''s no limit to how many people can sign in to online banking from the same computer. Just remember not to share your Username and Password.', N'SID_ACTIVE', N'FAQ_CAT_ID7', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID6', N'CH_ID_MOB_INT', N'FAQ_732018175346', N'Why do I see only some of my accounts on the dashboard?', N'Only accounts marked as Favorites are listed on the Dashboard screen. Favorite accounts are indicated with a filled in star next to the account name on the dashbaord list. Select the option "Show All Accounts" to view the remaining accounts. Click on the star next to an account to add it to Favorites or remove it from Favorites. ', N'SID_ACTIVE', N'FAQ_CAT_ID2', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID7', N'CH_ID_MOB_INT', N'FAQ_732018175547', N'Which account types are listed in the mobile/online banking applications?', N'The mobile and online banking apps support the following account types: Savings, Checking, Credit Cards, Loans, Deposits/Line of Credit.', N'SID_ACTIVE', N'FAQ_CAT_ID2', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID8', N'CH_ID_MOB_INT', N'FAQ_732018174748', N'Can I update my name from the Mobile and Online banking apps?', N'No. You cannot update your name from the applications, but you can download the Name Change Request form from the online banking application that you can print and submit at the bank.', N'SID_ACTIVE', N'FAQ_CAT_ID8', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[faqs] ([id], [Channel_id], [QuestionCode], [Question], [Answer], [Status_id], [FaqCategory_Id], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'FAQ_ID9', N'CH_ID_MOB_INT', N'FAQ_732018175949', N'Can I update my username and password for the mobile and online banking apps?', N'Yes, you can use the profile section to update the username or password as needed from the mobile and online banking apps.', N'SID_ACTIVE', N'FAQ_CAT_ID8', N'UID11', N'UID11', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
GO
INSERT [${dbxschemaname}].[privacypolicy] ([id], [Channel_id], [Status_id], [Description], [createdby], [modifiedby], [createdts], [lastmodifiedts], [synctimestamp], [softdeleteflag]) VALUES (N'PRIV_POL_ID1', NULL, N'SID_ACTIVE', N'<i><i><i>At Temenos Digital DBX Bank, the safeguarding of your account information is our top priority. We strive to keep our members informed on current security issues, as well as providing the tools to help protect yourself. Please check back periodically to view new information as it becomes available.<br /></i><br /><b><u>Your Account Security test</u></b></i></i><br /><i><i><b><u><br /><br /></u></b></i></i><br /><i><i><b><u><i>At Temenos Digital DBX Bank, the safeguarding of your account information is our top priority. We strive to keep our members informed on current security issues, as well as providing the tools to help protect yourself. Please check back periodically to view new information as it becomes available.<br /></i><br /><b><u>Your Account Security<br /></u></b><br />We protect your online security. Keeping financial and personal information about you secure and confidential is one of our most important responsibilities. Our systems are protected, so information remains secure.<ol><li>Computer virus protection detects and prevents computer viruses from entering our computer network systems.</li><li>Firewalls block unauthorized access by individuals or networks. Firewalls are just one way we protect our computer network systems that interact with the Internet.</li><li>Secure transmissions ensure information remains confidential. Temenos Digital DBX Bank uses encryption technology such as Secure Socket Layer (SSL) on its Web sites to securely transmit information between you and the bank.</li><li>Send secure e-mail to almost any department in the bank through the Contact Us section. Because an Internet e-mail response back to you may not be secure, we will not include confidential account information in an e-mail response. In addition, you will never be asked for confidential information, such as passwords or PINs, through e-mail. Besides e-mail, you can contact us by phone or visiting any branch.</li><li>Regular evaluations of our security features and continuous research of new advances in security technology ensure that your personal information is protecte</li></ol></u></b><br />We protect your online security. Keeping financial and personal information about you secure and confidential is one of our most important responsibilities. Our systems are protected, so information remains secure.<ol><li>Computer virus protection detects and prevents computer viruses from entering our computer network systems.</li><li>Firewalls block unauthorized access by individuals or networks. Firewalls are just one way we protect our computer network systems that interact with the Internet.</li><li>Secure transmissions ensure information remains confidential. Temenos Digital DBX Bank uses encryption technology such as Secure Socket Layer (SSL) on its Web sites to securely transmit information between you and the bank.</li><li>Send secure e-mail to almost any department in the bank through the Contact Us section. Because an Internet e-mail response back to you may not be secure, we will not include confidential account information in an e-mail response. In addition, you will never be asked for confidential information, such as passwords or PINs, through e-mail. Besides e-mail, you can contact us by phone or visiting any branch.</li><li>Regular evaluations of our security features and continuous research of new advances in security technology ensure that your personal information is protecte</li></ol>At Temenos Digital DBX Bank, the safeguarding of your account information is our top priority. We strive to keep our members informed on current security issues, as well as providing the tools to help protect yourself. Please check back periodically to view new information as it becomes available.<br /