INSERT [${dbxschemaname}].[policycontent] ([id], [Type_id], [Locale_Code], [Content], [createdby], [modifiedby], [createdts], [lastmodifiedts], [lastsynctimestamp], [softdeleteflag]) VALUES (N'POL1', N'PT_CUST_USERNAME', N'en-US', N'<ul class=""><li class="">The username should contain atleast 8 characters and atmost 64 characters</li><li class="">Must contain at least one special character. Only (&#39;.&#39;,&#39;-&#39;,&#39;_&#39;,&#39;&#64;&#39;,&#39;!&#39;,&#39;#&#39;,&#39;$&#39;) characters are allowed.</li><li class="">The username cannot contain the same consecutive special character</li><li class="">The first character of the username must be an ascii letter (a-z) or number (0-9)</li><li class="">The last character of the username must be an ascii letter (a-z) or number (0-9)</li></ul>', N'Kony User', N'Kony Dev', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
INSERT [${dbxschemaname}].[policycontent] ([id], [Type_id], [Locale_Code], [Content], [createdby], [modifiedby], [createdts], [lastmodifiedts], [lastsynctimestamp], [softdeleteflag]) VALUES (N'POL2', N'PT_CUST_PASSWORD', N'en-US', N'<ul class=""><li class="">The password should contain at least 8 characters and up to 64 characters</li><li class="">Must contain at least one special character, only the following are allowed: .-_@!#$</li><li class="">Password must contain at least one uppercase, one lowercase, and one number</li><li class="">Password can have up to 4 consecutive repeated characters</li></ul>', N'Kony User', N'Kony Dev', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, 0)
GO
