INSERT [${dbxschemaname}].[emailtemplates] ([id], [TemplateName], [TemplateText], [Subject], [SenderName], [SenderEmail], [AlertChannel], [AlertLanguageCode], [Alert_id]) VALUES (5, N'APPLICATION_SUCCESSFUL_SUBMISSION_EMAIL_TEMPLATE', N'<html> <head> <title> KONY HTML TEMPLATE </title> </head> <body> <table width="100%" align="center" cellpadding="0" cellspacing="0" border="0" valign="top" bgcolor="#FFFFFF"> <tbody> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:14px 24px;border-bottom:3px solid #0A78D1;font-family:sans-serif;font-weight:400;"> <img src="https://www.dropbox.com/s/yv01ja4p8mdmz65/konydbxlogo_customer_landing.png?raw=1" alt="logo" style="display:inline-block;float:left;vertical-align:middle;width:178px;height:35px;"/> <a target="_blanc" href="https://dbx.kony.com/" style="float:right;padding-top:11px;display:inline-block;font-size:14px;line-height:14px;text-decoration:none;color:#0A78D1;">dbx.kony.com</a> </td> </tr> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:25px 23px 0 23px;font-family:sans-serif;font-weight:400;"> <span style="font-family:sans-serif;font-size:12px;font-weight:400;line-height:14px;color:#000000;display:inline-block;">Dear</span> <span style="font-family:sans-serif;font-size:12px;font-weight:700;line-height:14px;color:#000000;display:inline-block;">%APPLICANT_NAME%,</span> </td> </tr> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:14px 23px 0 23px;font-family:sans-serif;font-weight:300;"> <span style="font-family:sans-serif;font-size:12px;font-weight:700;line-height:14px;color:#000000;display:inline-block;">We received your application on %DATE_OF_SUBMISSION% and appreciate your interest in %LOAN_TYPE%. </span> <span style="font-family:sans-serif;font-size:12px;font-weight:400;line-height:14px;color:#000000;display:inline-block;">For your reference your application number is %APPLICATION_NUMBER% If you recognize this application, no further action is necessary and you will receive additional details in upcoming communications.If you did not submit the application, please call us at %CONTACT_NUMBER%.</span> </td> </tr> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:14px 23px 0 23px;font-family:sans-serif;font-weight:300;"> <span style="font-family:sans-serif;font-size:12px;font-weight:400;line-height:14px;color:#000000;display:inline-block;">Thank you for choosing %BANK_CU_NAME% for your financial needs. </span> </td> </tr> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:20px 23px 0 23px;font-family:sans-serif;font-weight:300;"> <span style="font-family:sans-serif;font-size:12px;font-weight:400;line-height:14px;color:#000000;display:inline-block;">Sincerely, </span> </td> </tr> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:0px 23px 27px 23px;font-family:sans-serif;font-weight:300;border-bottom:1px solid #0A78D1"> <span style="font-family:sans-serif;font-size:12px;font-weight:700;line-height:14px;color:#000000;display:inline-block;">%BANK_CU_NAME%</span> </td> </tr> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:17px 23px 0px 23px;font-family:sans-serif;font-weight:300;"> <span style="font-family:sans-serif;font-size:11px;font-weight:400;line-height:13px;color:#000000;display:inline-block;">This is a system generated mail. Please do not reply to this e-mail ID.</span> </td> </tr> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:7px 23px 0px 23px;font-family:sans-serif;font-weight:300;"> <span style="font-family:sans-serif;font-size:12px;font-weight:700;line-height:14px;color:#000000;display:inline-block;">Have any questions?</span> </td> </tr> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:7px 23px 0px 23px;font-family:sans-serif;font-weight:300;"> <div style="width:100%;display:inline-block;padding:18px 11px;vertical-align:middle;text-align:left;border-radius:3px;border:1px solid #E6E6E6;background-color:#FFFFFF""> <span style="font-family:sans-serif;font-size:12px;font-weight:400;line-height:14px;color:#000000;display:inline-block;">We can help, call us at</span> <span style="font-family:sans-serif;font-size:12px;font-weight:700;line-height:14px;color:#000000;display:inline-block;">1800-412-5434</span> <span style="font-family:sans-serif;font-size:12px;font-weight:400;line-height:14px;color:#000000;display:inline-block;">for assistance</span> </div> </td> </tr> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:17px 23px 0px 23px;font-family:sans-serif;font-weight:300;"> <span style="font-family:sans-serif;font-size:10px;font-weight:400;line-height:12px;color:#000000;display:inline-block;">CONFIDENTIALITY INFORMATION AND DISCLAIMER</span> </td> </tr> <tr> <td style="width:100%;vertical-align:middle;text-align:left;padding:5px 23px 18px 23px;font-family:sans-serif;font-weight:300;"> <span style="font-family:sans-serif;font-size:10px;font-weight:400;line-height:12px;color:#000000;display:inline-block;">This e-mail message and its attachments may contain confidential, proprietary or legally privileged information and is intended solely for the use of the individual or entity to whom it is addressed. If you have erroneously received this message, please delete it immediately and notify the sender. If you are not the intended recipient of the e-mail message you should not disseminate, distribute or copy this e-mail. E-mail transmission cannot be guaranteed to be secure or error-free as information could be intercepted, corrupted, lost, destroyed, incomplete or contain viruses and the %BANK_CU_NAME% Bank accepts no liability for any damage caused by the limitations of the e-mail transmission.</span> </td> </tr> </tbody> </table> </body> </html>', N'Your Application for %LOAN_TYPE% is submitted.
